#!/usr/bin/env bash
# Start backend (:8000) and frontend (https://<ip>:5173, proxies /api) for local development.
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
trap 'kill 0' EXIT
# backend generated by turri (turri/backend.plain); the ML models stay in backend/models
# the demo database lives on the Linux side: on /mnt/c the startup seeding takes minutes
(cd "$ROOT/backend_turri" && APP_MODELS_DIR="$ROOT/backend/models" APP_DB_URL="${APP_DB_URL:-sqlite:///$HOME/ada_hack_demo.db}" uv run uvicorn app.main:app --host 0.0.0.0 --port 8000 --reload) &
(cd "$ROOT/frontend" && npm run dev) &
wait
